UPDATE "ReferenceCard" SET "name" = 'Energy Stored in a Capacitor', "symbol" = '$W_C$', "formulaLatex" = '$W_C = \frac{1}{2} C V^2$', "valueUnit" = '$\text{J}$', "description" = 'Energy held in a capacitor''s electric field.', "variables" = '[{"symbol":"$W_C$","meaning":"stored energy","unit":"$\\text{J}$"},{"symbol":"$C$","meaning":"capacitance","unit":"$\\text{F}$"},{"symbol":"$V$","meaning":"voltage across the plates","unit":"$\\text{V}$"}]'::jsonb, "purposeExamTip" = 'If charge is given instead of voltage, use $W_C = \frac{Q^2}{2C}$.', "dimensionless" = false, "updatedAt" = now()
