UPDATE "ReferenceCard" SET "name" = 'Resistance of a Conductor (Resistivity Formula)', "symbol" = '$R$', "formulaLatex" = '$R = \rho \frac{L}{A}$', "valueUnit" = '$\Omega$', "description" = 'Resistance of a uniform conductor from its material and size.', "variables" = '[{"symbol":"$R$","meaning":"resistance","unit":"$\\Omega$"},{"symbol":"$\\rho$","meaning":"resistivity of the material","unit":"$\\Omega\\cdot\\text{m}$"},{"symbol":"$L$","meaning":"length","unit":"$\\text{m}$"},{"symbol":"$A$","meaning":"cross-sectional area","unit":"$\\text{m}^2$"}]'::jsonb, "purposeExamTip" = 'Stretching a wire keeps its volume: double the length halves the area, so resistance goes up four times.', "dimensionless" = false, "updatedAt" = now()
