UPDATE "ReferenceCard" SET "name" = 'Temperature Dependence of Resistance', "symbol" = '$R_2$', "formulaLatex" = '$R_2 = R_1 [1 + \alpha_1 (T_2 - T_1)]$', "valueUnit" = '$\Omega$', "description" = 'Resistance of a conductor at a new temperature.', "variables" = '[{"symbol":"$R_2$","meaning":"resistance at the final temperature","unit":"$\\Omega$"},{"symbol":"$R_1$","meaning":"resistance at the reference temperature","unit":"$\\Omega$"},{"symbol":"$\\alpha_1$","meaning":"temperature coefficient at $T_1$","unit":"$^\\circ\\text{C}^{-1}$"},{"symbol":"$T_1$","meaning":"reference temperature","unit":"$^\\circ\\text{C}$"},{"symbol":"$T_2$","meaning":"final temperature","unit":"$^\\circ\\text{C}$"}]'::jsonb, "purposeExamTip" = '$\alpha_1$ must be the coefficient at $T_1$: a value quoted at $0^\circ\text{C}$ doesn''t apply from $20^\circ\text{C}$.', "dimensionless" = false, "updatedAt" = now()
WHERE "id" = '73fcf861-5bb8-405c-8906-cf892f019deb' AND "status" = 'LIVE';
UPDATE "ReferenceCard" SET "name" = 'Voltage Divider Rule (Two Resistors in Series)', "symbol" = '$V_x$', "formulaLatex" = '$V_x = V_s \frac{R_x}{R_1 + R_2}$', "valueUnit" = '$\text{V}$', "description" = 'Splits a voltage between series resistors in proportion to their resistance.', "variables" = '[{"symbol":"$V_x$","meaning":"voltage across the chosen resistor","unit":"$\\text{V}$"},{"symbol":"$V_s$","meaning":"source voltage","unit":"$\\text{V}$"},{"symbol":"$R_x$","meaning":"the chosen resistor","unit":"$\\Omega$"},{"symbol":"$R_1$","meaning":"first series resistor","unit":"$\\Omega$"},{"symbol":"$R_2$","meaning":"second series resistor","unit":"$\\Omega$"}]'::jsonb, "purposeExamTip" = 'It holds only if the same current flows through both, so no load can hang between them.', "dimensionless" = false, "updatedAt" = now()
WHERE "id" = '78e3caf8-8326-426d-b741-a2cbd50798cc' AND "status" = 'LIVE';
UPDATE "ReferenceCard" SET "name" = 'Active Power (Real Power)', "symbol" = '$P$', "formulaLatex" = '$P = V I \cos \theta$', "valueUnit" = '$\text{W}$', "description" = 'Power actually converted to work or heat.', "variables" = '[{"symbol":"$P$","meaning":"active power","unit":"$\\text{W}$"},{"symbol":"$V$","meaning":"RMS voltage","unit":"$\\text{V}$"},{"symbol":"$I$","meaning":"RMS current","unit":"$\\text{A}$"},{"symbol":"$\\theta$","meaning":"angle between voltage and current","unit":"$^\\circ$"}]'::jsonb, "purposeExamTip" = '$V$ and $I$ are RMS; with peak values, divide the product by 2.', "dimensionless" = false, "updatedAt" = now()
