UPDATE "ReferenceCard" SET "name" = 'Capacitive Reactance', "symbol" = '$X_C$', "formulaLatex" = '$X_C = \frac{1}{2\pi f C}$', "valueUnit" = '$\Omega$', "description" = 'Opposition of a capacitor to alternating current.', "variables" = '[{"symbol":"$X_C$","meaning":"capacitive reactance","unit":"$\\Omega$"},{"symbol":"$f$","meaning":"frequency","unit":"$\\text{Hz}$"},{"symbol":"$C$","meaning":"capacitance","unit":"$\\text{F}$"}]'::jsonb, "purposeExamTip" = 'Given $\omega$ in rad/s, use $X_C = \frac{1}{\omega C}$, with no extra $2\pi$.', "dimensionless" = false, "updatedAt" = now()
