UPDATE "ReferenceCard" SET "name" = 'Form Factor', "symbol" = '$\text{FF}$', "formulaLatex" = '$\text{FF} = \frac{E_{\text{rms}}}{E_{\text{ave}}}$', "valueUnit" = NULL, "description" = 'The ratio of a waveform''s RMS value to its average value.', "variables" = '[{"symbol":"$\\text{FF}$","meaning":"form factor","unit":null},{"symbol":"$E_{\\text{rms}}$","meaning":"RMS value","unit":"$\\text{V}$ or $\\text{A}$"},{"symbol":"$E_{\\text{ave}}$","meaning":"average value","unit":"$\\text{V}$ or $\\text{A}$"}]'::jsonb, "purposeExamTip" = 'A sine wave''s form factor is 1.11; don''t mix it up with peak factor, 1.414.', "dimensionless" = true, "updatedAt" = now()
