UPDATE "ReferenceCard" SET "name" = 'Inductive Reactance', "symbol" = '$X_L$', "formulaLatex" = '$X_L = 2\pi f L$', "valueUnit" = '$\Omega$', "description" = 'Opposition of an inductor to alternating current.', "variables" = '[{"symbol":"$X_L$","meaning":"inductive reactance","unit":"$\\Omega$"},{"symbol":"$f$","meaning":"frequency","unit":"$\\text{Hz}$"},{"symbol":"$L$","meaning":"inductance","unit":"$\\text{H}$"}]'::jsonb, "purposeExamTip" = 'Given $\omega$ in rad/s, use $X_L = \omega L$, with no extra $2\pi$.', "dimensionless" = false, "updatedAt" = now()
