UPDATE "ReferenceCard" SET "name" = 'Maximum Power Transfer Theorem', "symbol" = '$P_{\max}$', "formulaLatex" = '$P_{\max} = \frac{V_{th}^{2}}{4 R_{th}}$', "valueUnit" = '$\text{W}$', "description" = 'The most power a linear source can deliver to a resistive load.', "variables" = '[{"symbol":"$P_{\\max}$","meaning":"greatest power to the load","unit":"$\\text{W}$"},{"symbol":"$V_{th}$","meaning":"Thévenin voltage","unit":"$\\text{V}$"},{"symbol":"$R_{th}$","meaning":"Thévenin resistance","unit":"$\\Omega$"}]'::jsonb, "purposeExamTip" = 'It happens only at $R_L = R_{th}$, where efficiency is just 50%.', "dimensionless" = false, "updatedAt" = now()
WHERE "id" = '60069ed6-8b27-4cf9-a257-72bc4c7403aa' AND "status" = 'LIVE';
UPDATE "ReferenceCard" SET "name" = 'Peak Factor (Crest Factor)', "symbol" = '$\text{CF}$', "formulaLatex" = '$\text{CF} = \frac{E_m}{E_{\text{rms}}}$', "valueUnit" = NULL, "description" = 'The ratio of a waveform''s peak value to its RMS value.', "variables" = '[{"symbol":"$\\text{CF}$","meaning":"peak factor","unit":null},{"symbol":"$E_m$","meaning":"peak value","unit":"$\\text{V}$ or $\\text{A}$"},{"symbol":"$E_{\\text{rms}}$","meaning":"RMS value","unit":"$\\text{V}$ or $\\text{A}$"}]'::jsonb, "purposeExamTip" = 'A sine wave''s is $\sqrt{2} \approx 1.414$; form factor is the other ratio, 1.11.', "dimensionless" = true, "updatedAt" = now()
