UPDATE "ReferenceCard" SET "name" = 'Power Factor', "symbol" = '$\text{pf}$', "formulaLatex" = '$\text{pf} = \frac{P}{S} = \cos \theta$', "valueUnit" = NULL, "description" = 'How much of the apparent power does real work.', "variables" = '[{"symbol":"$\\text{pf}$","meaning":"power factor","unit":null},{"symbol":"$P$","meaning":"active power","unit":"$\\text{W}$"},{"symbol":"$S$","meaning":"apparent power","unit":"$\\text{VA}$"},{"symbol":"$\\theta$","meaning":"angle between voltage and current","unit":"$^\\circ$"}]'::jsonb, "purposeExamTip" = 'Leading means current leads voltage (capacitive); lagging means it lags (inductive).', "dimensionless" = true, "updatedAt" = now()
