UPDATE "ReferenceCard" SET "name" = 'Quality Factor of Series RLC Circuit', "symbol" = '$Q$', "formulaLatex" = '$Q = \frac{\omega_{0} L}{R}$', "valueUnit" = NULL, "description" = 'How sharply a series RLC circuit resonates.', "variables" = '[{"symbol":"$Q$","meaning":"quality factor","unit":null},{"symbol":"$\\omega_{0}$","meaning":"resonant angular frequency","unit":"$\\text{rad/s}$"},{"symbol":"$L$","meaning":"inductance","unit":"$\\text{H}$"},{"symbol":"$R$","meaning":"resistance","unit":"$\\Omega$"}]'::jsonb, "purposeExamTip" = 'Bandwidth is $f_0 / Q$, and $\omega_0$ must be in rad/s, not hertz.', "dimensionless" = true, "updatedAt" = now()
