UPDATE "ReferenceCard" SET "name" = 'Reactive Power', "symbol" = '$Q$', "formulaLatex" = '$Q = V I \sin \theta$', "valueUnit" = '$\text{var}$', "description" = 'Power that swings back and forth in inductors and capacitors, doing no net work.', "variables" = '[{"symbol":"$Q$","meaning":"reactive power","unit":"$\\text{var}$"},{"symbol":"$V$","meaning":"RMS voltage","unit":"$\\text{V}$"},{"symbol":"$I$","meaning":"RMS current","unit":"$\\text{A}$"},{"symbol":"$\\theta$","meaning":"angle between voltage and current","unit":"$^\\circ$"}]'::jsonb, "purposeExamTip" = 'Inductive loads absorb vars and capacitors supply them; power factor correction relies on this.', "dimensionless" = false, "updatedAt" = now()
