UPDATE "ReferenceCard" SET "name" = 'Resonant Frequency of Series RLC Circuit', "symbol" = '$f_{0}$', "formulaLatex" = '$f_{0} = \frac{1}{2\pi\sqrt{LC}}$', "valueUnit" = '$\text{Hz}$', "description" = 'The frequency where inductive and capacitive reactance cancel.', "variables" = '[{"symbol":"$f_{0}$","meaning":"resonant frequency","unit":"$\\text{Hz}$"},{"symbol":"$L$","meaning":"inductance","unit":"$\\text{H}$"},{"symbol":"$C$","meaning":"capacitance","unit":"$\\text{F}$"}]'::jsonb, "purposeExamTip" = 'At resonance the impedance is just $R$; $\omega_0 = \frac{1}{\sqrt{LC}}$ has no $2\pi$.', "dimensionless" = false, "updatedAt" = now()
