UPDATE "ReferenceCard" SET "name" = 'Sum of a Finite Geometric Progression', "symbol" = '$S_n$', "formulaLatex" = '$S_n = \frac{a_1(1 - r^n)}{1 - r}$', "valueUnit" = NULL, "description" = 'Adds the first terms of a sequence with a constant ratio.', "variables" = '[{"symbol":"$S_n$","meaning":"sum of the first $n$ terms","unit":null},{"symbol":"$a_1$","meaning":"first term","unit":null},{"symbol":"$r$","meaning":"common ratio","unit":null},{"symbol":"$n$","meaning":"number of terms","unit":null}]'::jsonb, "purposeExamTip" = 'It fails at $r = 1$, where the sum is $n a_1$. For an infinite sum with $|r| < 1$, $S = \frac{a_1}{1 - r}$.', "dimensionless" = false, "updatedAt" = now()
