UPDATE "ReferenceCard" SET "name" = 'Convergence Criterion for p-Series', "symbol" = NULL, "formulaLatex" = '$\sum_{n=1}^{\infty} \frac{1}{n^{p}}$', "valueUnit" = NULL, "description" = 'A benchmark series for comparison tests.', "variables" = '[{"symbol":"$n$","meaning":"term index","unit":null},{"symbol":"$p$","meaning":"the exponent","unit":null}]'::jsonb, "purposeExamTip" = 'It converges only for $p > 1$; at $p = 1$ it is the harmonic series, which diverges.', "dimensionless" = false, "updatedAt" = now()
WHERE "id" = '53d5f03f-b8db-4404-a565-c6454ba6816a' AND "status" = 'LIVE';
UPDATE "ReferenceCard" SET "name" = 'Radius of Convergence of Power Series', "symbol" = '$R$', "formulaLatex" = '$R = \lim_{n\to\infty} \left| \frac{a_{n}}{a_{n+1}} \right|$', "valueUnit" = NULL, "description" = 'How far from its center a power series converges.', "variables" = '[{"symbol":"$R$","meaning":"radius of convergence","unit":null},{"symbol":"$a_{n}$","meaning":"coefficient of the $n$-th term","unit":null}]'::jsonb, "purposeExamTip" = 'Check the two endpoints separately: this limit says nothing about them.', "dimensionless" = false, "updatedAt" = now()
WHERE "id" = '2db83565-f360-456d-812f-4843ba949aab' AND "status" = 'LIVE';
UPDATE "ReferenceCard" SET "name" = 'Imaginary Unit', "symbol" = '$i$', "formulaLatex" = NULL, "valueUnit" = '$\sqrt{-1}$', "description" = 'The number whose square is $-1$, written $j$ in electrical work.', "variables" = '[]'::jsonb, "purposeExamTip" = 'Powers cycle every four: $j^2 = -1$, $j^3 = -j$, $j^4 = 1$.', "dimensionless" = false, "updatedAt" = now()
WHERE "id" = 'b9067989-58ed-42e2-97d6-dce9f7137c57' AND "status" = 'LIVE';
UPDATE "ReferenceCard" SET "name" = 'Complex Number in Rectangular Form', "symbol" = '$z$', "formulaLatex" = '$z = x + iy$', "valueUnit" = NULL, "description" = 'A complex number as a point on the complex plane.', "variables" = '[{"symbol":"$z$","meaning":"the complex number","unit":null},{"symbol":"$x$","meaning":"real part","unit":null},{"symbol":"$y$","meaning":"imaginary part","unit":null}]'::jsonb, "purposeExamTip" = 'The imaginary part is $y$, not $iy$.', "dimensionless" = false, "updatedAt" = now()
WHERE "id" = '8a6f42ab-504d-4633-8b77-91f4f56693ad' AND "status" = 'LIVE';
UPDATE "ReferenceCard" SET "name" = 'De Moivre''s Theorem', "symbol" = '$z^n$', "formulaLatex" = '$z^n = r^n(\cos n\theta + i\sin n\theta)$', "valueUnit" = NULL, "description" = 'Raises a complex number in polar form to a power.', "variables" = '[{"symbol":"$r$","meaning":"modulus","unit":null},{"symbol":"$\\theta$","meaning":"argument","unit":"$\\text{rad}$"},{"symbol":"$n$","meaning":"the power","unit":null}]'::jsonb, "purposeExamTip" = 'Both change: raise $r$ to the power $n$ and multiply $\theta$ by $n$.', "dimensionless" = false, "updatedAt" = now()
WHERE "id" = '2092685b-4aaf-4d88-a0b2-1f27d88b7d1c' AND "status" = 'LIVE';
UPDATE "ReferenceCard" SET "name" = 'Euler''s Formula', "symbol" = '$e^{i\theta}$', "formulaLatex" = '$e^{i\theta} = \cos\theta + i\sin\theta$', "valueUnit" = NULL, "description" = 'Links the complex exponential to sine and cosine.', "variables" = '[{"symbol":"$\\theta$","meaning":"angle","unit":"$\\text{rad}$"}]'::jsonb, "purposeExamTip" = '$\theta$ must be in radians.', "dimensionless" = false, "updatedAt" = now()
WHERE "id" = '1f1601ec-9fe9-4113-838a-08fdf379c7c1' AND "status" = 'LIVE';
UPDATE "ReferenceCard" SET "name" = 'Pi', "symbol" = '$\pi$', "formulaLatex" = NULL, "valueUnit" = '$3.141592654$', "description" = 'The ratio of a circle''s circumference to its diameter.', "variables" = '[]'::jsonb, "purposeExamTip" = 'Use the calculator''s $\pi$ key, and check its angle mode before any trig.', "dimensionless" = false, "updatedAt" = now()
WHERE "id" = '06f4a9c6-5d75-4b73-9f95-c5d0579ad72d' AND "status" = 'LIVE';

