INSERT INTO "ReferenceCard" ("id", "kind", "symbol", "name", "formulaLatex", "valueUnit", "description", "variables", "purposeExamTip", "subject", "topicId", "subtopicTag", "dimensionless", "status", "createdAt", "updatedAt")
SELECT gen_random_uuid()::text, 'formula', '$F$', 'Coulomb''s Law', '$F = \frac{k\, q_1 q_2}{r^2}$', '$\text{N}$', 'The force between two point charges.', '[{"symbol":"$F$","meaning":"force between the charges","unit":"$\\text{N}$"},{"symbol":"$k$","meaning":"Coulomb constant","unit":"$\\text{N}\\cdot\\text{m}^2\\text{/C}^2$"},{"symbol":"$q_1, q_2$","meaning":"the charges","unit":"$\\text{C}$"},{"symbol":"$r$","meaning":"distance between them","unit":"$\\text{m}$"}]'::jsonb, 'Doubling $r$ gives a quarter of the force: it is an inverse square law.', 'EE', t."id", 'Electrostatics', false, 'PENDING', now(), now()
FROM "Topic" t WHERE t."name" = 'Electromagnetism' AND t."subject" = 'EE'
ON CONFLICT ("kind", "subject", "name") DO NOTHING;
INSERT INTO "ReferenceCard" ("id", "kind", "symbol", "name", "formulaLatex", "valueUnit", "description", "variables", "purposeExamTip", "subject", "topicId", "subtopicTag", "dimensionless", "status", "createdAt", "updatedAt")
SELECT gen_random_uuid()::text, 'formula', '$E$', 'Electric Field of a Point Charge', '$E = \frac{k\, q}{r^2}$', '$\text{N/C}$', 'Force per unit charge at a distance from a point charge.', '[{"symbol":"$E$","meaning":"field strength","unit":"$\\text{N/C}$"},{"symbol":"$k$","meaning":"Coulomb constant","unit":"$\\text{N}\\cdot\\text{m}^2\\text{/C}^2$"},{"symbol":"$q$","meaning":"the charge","unit":"$\\text{C}$"},{"symbol":"$r$","meaning":"distance","unit":"$\\text{m}$"}]'::jsonb, 'Field has direction and adds as vectors; potential is a scalar and adds directly.', 'EE', t."id", 'Electrostatics', false, 'PENDING', now(), now()
FROM "Topic" t WHERE t."name" = 'Electromagnetism' AND t."subject" = 'EE'
ON CONFLICT ("kind", "subject", "name") DO NOTHING;
INSERT INTO "ReferenceCard" ("id", "kind", "symbol", "name", "formulaLatex", "valueUnit", "description", "variables", "purposeExamTip", "subject", "topicId", "subtopicTag", "dimensionless", "status", "createdAt", "updatedAt")
SELECT gen_random_uuid()::text, 'formula', '$V$', 'Electric Potential of a Point Charge', '$V = \frac{k\, q}{r}$', '$\text{V}$', 'Work per unit charge to bring a charge in from infinity.', '[{"symbol":"$V$","meaning":"potential","unit":"$\\text{V}$"},{"symbol":"$k$","meaning":"Coulomb constant","unit":"$\\text{N}\\cdot\\text{m}^2\\text{/C}^2$"},{"symbol":"$q$","meaning":"the charge, with its sign","unit":"$\\text{C}$"},{"symbol":"$r$","meaning":"distance","unit":"$\\text{m}$"}]'::jsonb, 'It falls with $r$, not $r^2$, and keeps the sign of the charge.', 'EE', t."id", 'Electrostatics', false, 'PENDING', now(), now()
FROM "Topic" t WHERE t."name" = 'Electromagnetism' AND t."subject" = 'EE'
ON CONFLICT ("kind", "subject", "name") DO NOTHING;
INSERT INTO "ReferenceCard" ("id", "kind", "symbol", "name", "formulaLatex", "valueUnit", "description", "variables", "purposeExamTip", "subject", "topicId", "subtopicTag", "dimensionless", "status", "createdAt", "updatedAt")
SELECT gen_random_uuid()::text, 'formula', '$C$', 'Capacitance of a Parallel-Plate Capacitor', '$C = \frac{\varepsilon_r \varepsilon_0 A}{d}$', '$\text{F}$', 'Capacitance from a capacitor''s size and dielectric.', '[{"symbol":"$C$","meaning":"capacitance","unit":"$\\text{F}$"},{"symbol":"$\\varepsilon_r$","meaning":"relative permittivity of the dielectric","unit":null},{"symbol":"$\\varepsilon_0$","meaning":"permittivity of free space","unit":"$\\text{F/m}$"},{"symbol":"$A$","meaning":"plate area","unit":"$\\text{m}^2$"},{"symbol":"$d$","meaning":"plate spacing","unit":"$\\text{m}$"}]'::jsonb, 'Convert $\text{cm}^2$ and $\text{mm}$ to SI first, and for $n$ plates use $n - 1$ gaps.', 'EE', t."id", 'Electrostatics', false, 'PENDING', now(), now()
FROM "Topic" t WHERE t."name" = 'Electromagnetism' AND t."subject" = 'EE'
ON CONFLICT ("kind", "subject", "name") DO NOTHING;
INSERT INTO "ReferenceCard" ("id", "kind", "symbol", "name", "formulaLatex", "valueUnit", "description", "variables", "purposeExamTip", "subject", "topicId", "subtopicTag", "dimensionless", "status", "createdAt", "updatedAt")
SELECT gen_random_uuid()::text, 'formula', '$B$', 'Magnetic Field of a Long Straight Conductor', '$B = \frac{\mu_0 I}{2\pi r}$', '$\text{T}$', 'The field around a long wire carrying current.', '[{"symbol":"$B$","meaning":"flux density","unit":"$\\text{T}$"},{"symbol":"$\\mu_0$","meaning":"permeability of free space","unit":"$\\text{H/m}$"},{"symbol":"$I$","meaning":"current","unit":"$\\text{A}$"},{"symbol":"$r$","meaning":"distance from the conductor","unit":"$\\text{m}$"}]'::jsonb, 'It falls with $r$, not $r^2$; the direction comes from the right-hand rule.', 'EE', t."id", 'Magnetic Fields', false, 'PENDING', now(), now()
FROM "Topic" t WHERE t."name" = 'Electromagnetism' AND t."subject" = 'EE'
ON CONFLICT ("kind", "subject", "name") DO NOTHING;
INSERT INTO "ReferenceCard" ("id", "kind", "symbol", "name", "formulaLatex", "valueUnit", "description", "variables", "purposeExamTip", "subject", "topicId", "subtopicTag", "dimensionless", "status", "createdAt", "updatedAt")
SELECT gen_random_uuid()::text, 'formula', '$F$', 'Force on a Current-Carrying Conductor', '$F = B I L \sin\theta$', '$\text{N}$', 'The push on a wire in a magnetic field, behind every motor.', '[{"symbol":"$F$","meaning":"force","unit":"$\\text{N}$"},{"symbol":"$B$","meaning":"flux density","unit":"$\\text{T}$"},{"symbol":"$I$","meaning":"current","unit":"$\\text{A}$"},{"symbol":"$L$","meaning":"length in the field","unit":"$\\text{m}$"},{"symbol":"$\\theta$","meaning":"angle between conductor and field","unit":"$^\\circ$"}]'::jsonb, 'It is greatest at $\theta = 90^\circ$ and zero when the wire runs along the field.', 'EE', t."id", 'Magnetic Fields', false, 'PENDING', now(), now()
FROM "Topic" t WHERE t."name" = 'Electromagnetism' AND t."subject" = 'EE'
ON CONFLICT ("kind", "subject", "name") DO NOTHING;
INSERT INTO "ReferenceCard" ("id", "kind", "symbol", "name", "formulaLatex", "valueUnit", "description", "variables", "purposeExamTip", "subject", "topicId", "subtopicTag", "dimensionless", "status", "createdAt", "updatedAt")
SELECT gen_random_uuid()::text, 'formula', '$F/L$', 'Force Between Parallel Conductors', '$\frac{F}{L} = \frac{\mu_0 I_1 I_2}{2\pi d}$', '$\text{N/m}$', 'Force per metre between two long parallel wires.', '[{"symbol":"$F/L$","meaning":"force per unit length","unit":"$\\text{N/m}$"},{"symbol":"$\\mu_0$","meaning":"permeability of free space","unit":"$\\text{H/m}$"},{"symbol":"$I_1, I_2$","meaning":"the currents","unit":"$\\text{A}$"},{"symbol":"$d$","meaning":"spacing","unit":"$\\text{m}$"}]'::jsonb, 'Currents in the same direction attract; opposite directions repel.', 'EE', t."id", 'Magnetic Fields', false, 'PENDING', now(), now()
FROM "Topic" t WHERE t."name" = 'Electromagnetism' AND t."subject" = 'EE'
ON CONFLICT ("kind", "subject", "name") DO NOTHING;
INSERT INTO "ReferenceCard" ("id", "kind", "symbol", "name", "formulaLatex", "valueUnit", "description", "variables", "purposeExamTip", "subject", "topicId", "subtopicTag", "dimensionless", "status", "createdAt", "updatedAt")
SELECT gen_random_uuid()::text, 'formula', '$e$', 'Faraday''s Law of Induction', '$e = -N \frac{d\Phi}{dt}$', '$\text{V}$', 'The EMF induced by a changing magnetic flux.', '[{"symbol":"$e$","meaning":"induced EMF","unit":"$\\text{V}$"},{"symbol":"$N$","meaning":"number of turns","unit":null},{"symbol":"$\\Phi$","meaning":"flux through the coil","unit":"$\\text{Wb}$"},{"symbol":"$t$","meaning":"time","unit":"$\\text{s}$"}]'::jsonb, 'The minus sign is Lenz''s law: the EMF opposes the change that made it.', 'EE', t."id", 'Induction', false, 'PENDING', now(), now()
FROM "Topic" t WHERE t."name" = 'Electromagnetism' AND t."subject" = 'EE'
ON CONFLICT ("kind", "subject", "name") DO NOTHING;
INSERT INTO "ReferenceCard" ("id", "kind", "symbol", "name", "formulaLatex", "valueUnit", "description", "variables", "purposeExamTip", "subject", "topicId", "subtopicTag", "dimensionless", "status", "createdAt", "updatedAt")
SELECT gen_random_uuid()::text, 'formula', '$e$', 'Motional EMF', '$e = B L v \sin\theta$', '$\text{V}$', 'The EMF in a conductor moving through a field, behind every generator.', '[{"symbol":"$e$","meaning":"induced EMF","unit":"$\\text{V}$"},{"symbol":"$B$","meaning":"flux density","unit":"$\\text{T}$"},{"symbol":"$L$","meaning":"length of conductor","unit":"$\\text{m}$"},{"symbol":"$v$","meaning":"speed","unit":"$\\text{m/s}$"},{"symbol":"$\\theta$","meaning":"angle between motion and field","unit":"$^\\circ$"}]'::jsonb, 'Only motion across the field counts; moving along it induces nothing.', 'EE', t."id", 'Induction', false, 'PENDING', now(), now()
FROM "Topic" t WHERE t."name" = 'Electromagnetism' AND t."subject" = 'EE'
ON CONFLICT ("kind", "subject", "name") DO NOTHING;
INSERT INTO "ReferenceCard" ("id", "kind", "symbol", "name", "formulaLatex", "valueUnit", "description", "variables", "purposeExamTip", "subject", "topicId", "subtopicTag", "dimensionless", "status", "createdAt", "updatedAt")
SELECT gen_random_uuid()::text, 'formula', '$L$', 'Inductance of a Solenoid', '$L = \frac{\mu_r \mu_0 N^2 A}{l}$', '$\text{H}$', 'Inductance from a coil''s size, turns and core.', '[{"symbol":"$L$","meaning":"inductance","unit":"$\\text{H}$"},{"symbol":"$\\mu_r$","meaning":"relative permeability of the core","unit":null},{"symbol":"$\\mu_0$","meaning":"permeability of free space","unit":"$\\text{H/m}$"},{"symbol":"$N$","meaning":"number of turns","unit":null},{"symbol":"$A$","meaning":"cross-sectional area","unit":"$\\text{m}^2$"},{"symbol":"$l$","meaning":"length of the coil","unit":"$\\text{m}$"}]'::jsonb, 'It goes with $N^2$: doubling the turns gives four times the inductance.', 'EE', t."id", 'Induction', false, 'PENDING', now(), now()
FROM "Topic" t WHERE t."name" = 'Electromagnetism' AND t."subject" = 'EE'
ON CONFLICT ("kind", "subject", "name") DO NOTHING;
