SELECT gen_random_uuid()::text, 'formula', '$M$', 'Mutual Inductance', '$M = k \sqrt{L_1 L_2}$', '$\text{H}$', 'How strongly two coils are linked.', '[{"symbol":"$M$","meaning":"mutual inductance","unit":"$\\text{H}$"},{"symbol":"$k$","meaning":"coupling coefficient, 0 to 1","unit":null},{"symbol":"$L_1, L_2$","meaning":"self-inductances","unit":"$\\text{H}$"}]'::jsonb, 'Series aiding gives $L_1 + L_2 + 2M$; series opposing gives $L_1 + L_2 - 2M$.', 'EE', t."id", 'Induction', false, 'PENDING', now(), now()
FROM "Topic" t WHERE t."name" = 'Electromagnetism' AND t."subject" = 'EE'
