SELECT gen_random_uuid()::text, 'formula', '$\mathcal{F}$', 'Magnetomotive Force', '$\mathcal{F} = N I$', '$\text{A}\cdot\text{t}$', 'What drives flux around a magnetic circuit, like voltage in an electric one.', '[{"symbol":"$\\mathcal{F}$","meaning":"magnetomotive force","unit":"$\\text{A}\\cdot\\text{t}$"},{"symbol":"$N$","meaning":"number of turns","unit":null},{"symbol":"$I$","meaning":"current","unit":"$\\text{A}$"}]'::jsonb, 'Field intensity is this per unit length: $H = \frac{N I}{l}$.', 'EE', t."id", 'Magnetic Circuits', false, 'PENDING', now(), now()
FROM "Topic" t WHERE t."name" = 'Electromagnetism' AND t."subject" = 'EE'
ON CONFLICT ("kind", "subject", "name") DO NOTHING;
INSERT INTO "ReferenceCard" ("id", "kind", "symbol", "name", "formulaLatex", "valueUnit", "description", "variables", "purposeExamTip", "subject", "topicId", "subtopicTag", "dimensionless", "status", "createdAt", "updatedAt")
SELECT gen_random_uuid()::text, 'formula', '$\mathcal{R}$', 'Reluctance', '$\mathcal{R} = \frac{l}{\mu_r \mu_0 A}$', '$\text{A}\cdot\text{t/Wb}$', 'Opposition to flux, like resistance in an electric circuit.', '[{"symbol":"$\\mathcal{R}$","meaning":"reluctance","unit":"$\\text{A}\\cdot\\text{t/Wb}$"},{"symbol":"$l$","meaning":"length of the path","unit":"$\\text{m}$"},{"symbol":"$\\mu_r$","meaning":"relative permeability","unit":null},{"symbol":"$\\mu_0$","meaning":"permeability of free space","unit":"$\\text{H/m}$"},{"symbol":"$A$","meaning":"area of the path","unit":"$\\text{m}^2$"}]'::jsonb, 'Then $\Phi = \frac{\mathcal{F}}{\mathcal{R}}$, and an air gap often dominates the total.', 'EE', t."id", 'Magnetic Circuits', false, 'PENDING', now(), now()
FROM "Topic" t WHERE t."name" = 'Electromagnetism' AND t."subject" = 'EE'
ON CONFLICT ("kind", "subject", "name") DO NOTHING;
