SELECT gen_random_uuid()::text, 'constant', '$k$', 'Coulomb Constant', NULL, '$8.988 \times 10^{9}\ \text{N}\cdot\text{m}^2\text{/C}^2$', 'The constant in Coulomb''s law for a vacuum.', '[]'::jsonb, 'It equals $\frac{1}{4\pi\varepsilon_0}$, and is often rounded to $9 \times 10^9$ in problems.', 'EE', t."id", 'Electrostatics', false, 'PENDING', now(), now()
